CREATE POLICY "Owners upload project references" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'project-references' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Owners read project references" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'project-references' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Owners delete project references" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'project-references' AND (storage.foldername(name))[1] = auth.uid()::text);